81	function poll(repo: string, number: string, since: Date): boolean {
82	  const { code, stdout } = gh(
83	    "api", `repos/${repo}/issues/${number}/comments`,
84	    "--method", "GET",
85	    "-f", `since=${since.toISOString()}`,
86	    "--jq", "[.[] | {body, created_at}]",
87	  );
88	  if (code !== 0) return false;
89	  try {
90	    return stopRequested(JSON.parse(stdout || "[]") as StopComment[], since);
91	  } catch {
92	    return false;
93	  }
